{
  "description": "A quadrupedal creature shown in right-facing profile standing on a plain light background. The overall body shape, fur, head, hind legs and tail are those of a large gray wolf with thick shaggy fur that is darker gray on the back and sides and lighter gray-white on the underside, chest and muzzle. The dorsal back, shoulders and parts of the limbs are covered by a hard, glossy, dark gray-green segmented shell with scalloped edges. The two forelimbs are not wolf legs but thick, jointed, armored limbs ending in large crab-like pincers that rest on the ground and support weight, while the two hind limbs remain wolf-like paws with claws.",
  "parts": [
    {
      "part": "head",
      "looks_like": "wolf-like with elongated snout, black nose, amber eye with dark pupil, gray fur on top and white-gray on muzzle and cheek, whiskers visible",
      "where": "at the front/anterior end of the body, facing right"
    },
    {
      "part": "ears",
      "looks_like": "two upright triangular pointed ears with dark inner fur and gray outer fur",
      "where": "on top of the head, one slightly behind the other in profile"
    },
    {
      "part": "mane",
      "looks_like": "thick, long, shaggy ruff of gray and white fur",
      "where": "around the neck, throat and chest extending back to the shoulders"
    },
    {
      "part": "legs",
      "looks_like": "four limbs: two hind limbs are slender, fur-covered wolf legs with visible joints; two forelimbs are thick, heavily armored, jointed crab-like chelipeds with segmented plating and spiny, bumpy texture on the lower segments",
      "where": "two hind legs under the hips at the rear, two front legs under the shoulders at the front, all supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "hind feet are wolf paws with fur and four dark claws each; front feet are large crab pincers/claws with dark tips, bumpy textured surface and a movable lower finger",
      "where": "at the ends of the limbs touching the ground"
    },
    {
      "part": "tail",
      "looks_like": "long, bushy, thick-furred wolf tail, gray with darker tip, hanging down",
      "where": "at the rear/posterior end of the body"
    },
    {
      "part": "shell",
      "looks_like": "large, hard, glossy, dark gray-green carapace with smooth domed surface and scalloped, spiny edges, divided into overlapping segments",
      "where": "covering the dorsal back from behind the shoulders to the hips, with a separate smaller shield over the shoulder"
    },
    {
      "part": "plates",
      "looks_like": "smaller overlapping armored plates with ridged, scalloped margins and some spines, same dark glossy material as the shell, with tan-brown membrane visible at joints",
      "where": "along the sides of the shell, over the shoulder joint, on the upper forelimbs, and as a vertical row and joint rings on the hind legs"
    },
    {
      "part": "markings",
      "looks_like": "natural wolf coloration: darker gray on back and outer legs, lighter cream-white on belly, inner legs and muzzle, no artificial patterns",
      "where": "over the fur of the entire body"
    }
  ],
  "attached_objects": [],
  "animals": ["wolf", "crab"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
